#include <bits/stdc++.h>
using namespace std;

template<typename T> void print_debug_info(const char *label, T val) { cerr << label << '=' << val << endl; }
template<typename T, typename... Args> void print_debug_info(const char *label, T val, Args... args) {
  while(*label != ',') cerr << *label++;
  cerr << '=' << val << ','; print_debug_info(label + 1, args...);
}
template<typename T> ostream &operator<<(ostream &os, vector<T> v) {
  os << "["; for (auto &x : v) os << x << ","; return os << "]";
}
template<typename L, typename R> ostream &operator<<(ostream &os, pair<L, R> p) {
  return os << "(" << p.first << "," << p.second << ")";
}
#define debug(...) print_debug_info(#__VA_ARGS__, __VA_ARGS__)

vector<long long> sequence_vals;
long long compute_value(long long n, long long l) {
  long long quotient = n / sequence_vals[l];
  n %= sequence_vals[l];
  if (n == 0) return quotient * l;
  return quotient * l + min(l + compute_value(sequence_vals[l] - n, l - 1), compute_value(n, l - 1));
}

int main() {
  ios::sync_with_stdio(false); cin.tie(nullptr);
  long long t = 1, n;
  sequence_vals.resize(17);
  long long current = 0;
  for (int i = 0; i < 17; ++i) {
    sequence_vals[i] = current;
    current = current * 10 + 1;
  }
  while (t--) {
    cin >> n;
    cout << compute_value(n, 16);
  }
}
